  <header class="dashboard-heading learning-heading"><div><p class="eyebrow"><?= $escape($lesson['module_title']) ?></p><h1><?= $escape($lesson['lesson_title']) ?></h1><p><?= $escape($lesson['course_title']) ?></p></div></header>
